command:example.dev:code:
$log = New-ConsoleLog -Height 5
$log | Add-ConsoleItem { New-ConsoleLogEntry 'Discovered 4 domain controllers' -At 2s }
$log | Add-ConsoleItem { New-ConsoleLogEntry 'DC02 lags by 42 minutes' -Level Warning -At 31s }
$log | Write-ConsoleWidget

$tree = New-ConsoleTree 'Shares'
foreach ($share in Get-SmbShare) {
    $tree | Add-ConsoleItem { New-ConsoleTreeNode $share.Name -Detail $share.Path }
}
$tree | Write-ConsoleWidget

It 'renders the report table' {
    $rows | Format-ConsoleTable -AsWidget | Assert-ConsoleOutput -GoldenPath "$PSScriptRoot\Golden\report.txt" -Width 80
}

1..40 | Invoke-ConsoleRun -Parallel -ThrottleLimit 8 -TimeoutSeconds 10 -Title 'Patching web farm' -Name { "web$('{0:d2}' -f $_)" } {
    Start-Sleep -Milliseconds (Get-Random -Minimum 200 -Maximum 1500)
    if ($_ % 13 -eq 0) { throw "web$_ did not come back after the reboot" }
}

$dashboard = New-ConsoleDashboard -Title 'Checks' { New-ConsolePanel -Title 'Running' { New-ConsoleActivityList -Name running -MaxVisible 4 } }
Start-ConsoleDashboard $dashboard {
    Update-ConsoleActivity -Name running -Id 1 -Activity 'SRV01 · Free space'
    Start-Sleep -Seconds 1
    Update-ConsoleActivity -Name running -Id 1 -Complete
}

New-ConsoleBarChart -Stacked {
    New-ConsoleBarItem 'Passed' 412 -Tone Pass
    New-ConsoleBarItem 'Warnings' 51 -Tone Warn
    New-ConsoleBarItem 'Failed' 23 -Tone Fail
} | Write-ConsoleWidget

New-ConsoleBarChart -Stacked {
    New-ConsoleBarItem 'Passed' 412 -Tone Pass
    New-ConsoleBarItem 'Warnings' 51 -Tone Warn
    New-ConsoleBarItem 'Failed' 23 -Tone Fail
} | Write-ConsoleWidget

New-ConsoleBarChart -Unit ' ms' {
    New-ConsoleBarItem 'Cloudflare' 12
    New-ConsoleBarItem 'Quad9' 64 -Tone Warn
} | Write-ConsoleWidget

$completed = foreach ($i in 0..47) { 20 + 9 * [math]::Sin($i / 7) + $i % 3 }
$failed = foreach ($i in 0..47) { 3 + 2 * [math]::Cos($i / 5) }
New-ConsoleLineChart -Height 7 {
    New-ConsoleChartSeries 'completed' -Value $completed -Tone Accent
    New-ConsoleChartSeries 'failed' -Value $failed -Tone Fail
} | Write-ConsoleWidget

New-ConsoleMenuItem 'Run checks' -Action {
    $clock = New-ConsoleClock -Speed 7
    $dashboard = New-ConsoleDashboard -Title 'Checks' { New-ConsoleSummaryBar -Total 3; New-ConsoleLog -Height 5 }
    $null = $MenuContext.Run($dashboard, {
        foreach ($done in 1..3) {
            $clock.Wait(4.5)
            Update-ConsoleSummaryBar -Done $done -Counter @{ passed = $done }
            Write-ConsoleLog "Check $done passed"
        }
        New-ConsoleRunResult 'Checks finished'
    }, $clock)
}

$clock = New-ConsoleClock -Speed 10
Start-ConsoleDashboard $dashboard -Clock $clock -ArgumentList $clock, $entries {
    param($Clock, $Entries)
    foreach ($entry in $Entries) { $Clock.WaitUntil($entry.Seconds); Write-ConsoleLog $entry.Text }
}

New-ConsoleColumns -FixedWidth 0, 0, 17 -CollapseBelow 90 {
    New-ConsolePanel -Title 'Failures' -Weight 1.5 { New-ConsoleLiveTable -Name failures -Column 'Server', 'Check' }
    New-ConsolePanel -Title 'Slowest' { New-ConsoleLiveTable -Name slowest -Column 'Check', 'Took' }
    New-ConsolePanel -Title 'Durations' { New-ConsoleHistogram -Name durations -Edge 0, 2, 4, 8 -Height 5 }
}

New-ConsoleField Servers 'Servers' -Type MultiSelect -DependsOn Domain -Parameter ComputerName -LoadChoices {
    param($Values)
    Get-AppServer -Domain $Values.Domain | ForEach-Object {
        [pscustomobject] @{ Name = $_.Name; Site = $_.Site; Role = $_.Role; Offline = $_.OfflineReason; Online = -not $_.OfflineReason }
    }
} -Display Name -CommandValue Name -GroupBy Site -Badge Role -Disabled Offline -Selected Online

$form = New-ConsoleForm 'New share' -Command 'New-AppShare' {
    New-ConsoleField Name 'Share name' -Page Basics -Required -Parameter Name
    New-ConsoleField Path 'Folder' -Type Path -Kind Folder -MustExist -Page Basics -Parameter Path
    New-ConsoleField ReadOnly 'Read only' -Type Toggle -Page Access -Parameter ReadOnly
}

$form = New-ConsoleForm 'New share' -Command 'New-AppShare' {
    New-ConsoleField Name 'Share name' -Required -Parameter Name
    New-ConsoleField ReadOnly 'Read only' -Type Toggle -Parameter ReadOnly
    New-ConsoleFormPreset 'Archive' -Values @{ Name = 'Archive'; ReadOnly = $true } -Description 'A read-only archive share.'
}

$form = New-ConsoleForm 'Report' -Command 'Export-AppReport' {
    New-ConsoleField Period 'Period' -Type Select -Choices 'Day', 'Week', 'Month' -Parameter Period
    New-ConsoleField Path 'Folder' -Type Path -Kind Folder -Parameter Path
    New-ConsoleFormPreset 'Weekly' -Values @{ Period = 'Week'; Path = 'D:\Reports\Weekly' } -Description 'Every Monday.'
    New-ConsoleFormPreset 'Monthly' -Values @{ Period = 'Month'; Path = 'D:\Reports\Monthly' }
}
Read-ConsoleForm $form -Preset Weekly

New-ConsoleKeyValue {
    New-ConsoleKeyValueItem 'Version' '0.0.4 [muted]→[/] [bold]2.0.0[/]' -Markup
    New-ConsoleKeyValueItem 'Signing' 'skipped' -Status Skip
    New-ConsoleKeyValueItem 'Tests' '1 skipped on PowerShell 7' -Status Warn
} | Write-ConsoleWidget

New-ConsoleKeyValue ([ordered] @{ Module = 'ConsoleMonster'; Frameworks = 'netstandard2.0, net472, net8.0' }) {
    New-ConsoleKeyValueItem 'Signing' 'skipped' -Status Skip
} | Write-ConsoleWidget

New-ConsoleKeyValue {
    New-ConsoleKeyValueItem 'Module' '[bold]ConsoleMonster[/]' -Markup
    New-ConsoleKeyValueItem 'Signing' 'skipped' -Status Skip
    New-ConsoleKeyValueItem 'Tests' '1 skipped on PowerShell 7' -Status Warn
} | Write-ConsoleWidget

New-ConsoleKeyValue {
    New-ConsoleKeyValueItem 'Package size' 1482113 -Presenter Bytes
    New-ConsoleKeyValueItem 'Built in' (New-TimeSpan -Seconds 48) -Presenter Duration
} | Write-ConsoleWidget

New-ConsoleLanes {
    New-ConsoleLane 'DC01' -Total 40 -Done 40 -Status Pass -Passed 40
    New-ConsoleLane 'DC02' -Total 40 -Done 22 -Status Running -Passed 21 -Warned 1 -Detail 'replication'
    New-ConsoleLane 'DC03' -Total 40
} | Write-ConsoleWidget

New-ConsoleLanes {
    New-ConsoleLane 'DC01' -Total 40 -Done 40 -Status Pass -Passed 40
    New-ConsoleLane 'DC02' -Total 40 -Done 22 -Status Running -Passed 21 -Warned 1 -Detail 'replication'
    New-ConsoleLane 'DC03' -Total 40
} | Write-ConsoleWidget

$completed = foreach ($i in 0..47) { 20 + 9 * [math]::Sin($i / 7) + $i % 3 }
$failed = foreach ($i in 0..47) { 3 + 2 * [math]::Cos($i / 5) }
New-ConsoleLineChart -Height 7 {
    New-ConsoleChartSeries 'completed' -Value $completed -Tone Accent
    New-ConsoleChartSeries 'failed' -Value $failed -Tone Fail
} | Write-ConsoleWidget

New-ConsoleLog -Height 5 {
    New-ConsoleLogEntry 'Discovered 4 domain controllers in 2 domains' -Level Info -At 2s
    New-ConsoleLogEntry 'DC02: USN rollback check failed (event 2095)' -Level Error -At 44s
    New-ConsoleLogEntry 'Using cached schema snapshot' -Level Verbose -At 53s
} | Write-ConsoleWidget

New-ConsoleLog -Height 5 {
    New-ConsoleLogEntry 'Discovered 4 domain controllers in 2 domains' -Level Info -At 2s
    New-ConsoleLogEntry 'DC02: replication partner DC05 last success 3h ago' -Level Warning -At 31s
    New-ConsoleLogEntry 'DC02: USN rollback check failed (event 2095)' -Level Error -At 44s
} | Write-ConsoleWidget

$events = Import-Csv deploy-events.csv
New-ConsoleLog {
    foreach ($event in $events) { New-ConsoleLogEntry $event.Message -Level $event.Level -At $event.Seconds }
} | Write-ConsoleWidget

$menu = New-ConsoleMenu 'Backup helper' {
    New-ConsoleMenuItem 'Back up now' -Hotkey b -Action { Start-Backup }
    New-ConsoleMenuItem 'Settings' -Hotkey s -Form $settings
    New-ConsoleMenuItem -Exit
}
Show-ConsoleMenu $menu -Layout Classic

$form = New-ConsoleForm 'Backup' -Command 'Start-AppBackup' {
    New-ConsoleField Target 'Target' -Type Select -Choices 'Daily', 'Weekly' -Parameter Target
    New-ConsoleField Compress 'Compress' -Type Toggle -Parameter Compress
}
$menu = New-ConsoleMenu 'Backup helper' {
    New-ConsoleMenuPreset 'Weekly · compressed' -Description 'The Sunday backup.' -Form $form -Values @{ Target = 'Weekly'; Compress = $true } -Preview {
        New-ConsoleKeyValue -Data ([ordered] @{ Target = 'Weekly'; Compress = 'yes' })
    }
    New-ConsoleMenuItem 'Presets' -Presets
    New-ConsoleMenuItem 'Back up' -Form $form
    New-ConsoleMenuItem -Exit
}

New-ConsolePhases {
    New-ConsoleStatusItem 'Discover' -Status Pass -Detail '2.1s'
    New-ConsoleStatusItem 'Collect' -Status Pass -Detail '14s'
    New-ConsoleStatusItem 'Evaluate' -Status Running -Detail '64%'
    New-ConsoleStatusItem 'Report'
} | Write-ConsoleWidget

New-ConsoleRows {
    New-ConsoleProgress 'Build' -Value 64 -Total 100
    New-ConsoleProgress 'Docs' -Value 100 -Total 100 -Status Pass
    New-ConsoleProgress 'Upload' -Value 3 -Total 8 -Shape Block
} | Write-ConsoleWidget

New-ConsoleMenuItem 'Back up now' -Action {
    $dashboard = New-ConsoleDashboard -Title 'Backup' { New-ConsoleStatusList -Item 'Scan files', 'Copy changes' }
    $null = $MenuContext.Run($dashboard, {
        Update-ConsoleStatus 'Scan files' -Status Pass
        Update-ConsoleStatus 'Copy changes' -Status Pass
        New-ConsoleRunResult 'Backup finished' -Summary '1 284 files copied, 312 MB.' -Figure ([ordered] @{ files = '1 284'; copied = '312 MB' }) -Next @{
            'Show where the log is' = { $MenuContext.Toast('Log: D:\Backups\backup.log') }
        }
    })
}

New-ConsoleStack {
    New-ConsoleLineChart -Name latency
    New-ConsoleAlign -Horizontal Right { New-ConsoleText -Markup '[pass]LIVE[/]' }
}

New-ConsoleStatusList {
    New-ConsoleStatusItem 'Restore NuGet packages' -Status Pass -Detail '1.6 s'
    New-ConsoleStatusItem 'Run Pester on PowerShell 7' -Status Warn -Detail '1 skipped'
    New-ConsoleStatusItem 'Publish to PowerShell Gallery' -Status Pending
} | Write-ConsoleWidget

New-ConsolePhases {
    New-ConsoleStatusItem 'Discover' -Status Pass -Detail '2.1s'
    New-ConsoleStatusItem 'Evaluate' -Status Running -Detail '64%'
    New-ConsoleStatusItem 'Report'
} | Write-ConsoleWidget

New-ConsoleStatusList {
    New-ConsoleStatusItem 'Restore NuGet packages' -Status Pass -Detail '1.6 s'
    New-ConsoleStatusItem 'Compile ConsoleMonster' -Status Pass -Detail '4.7 s'
    New-ConsoleStatusItem 'Run Pester on PowerShell 7' -Status Warn -Detail '1 skipped'
    New-ConsoleStatusItem 'Pack ConsoleMonster.2.0.0.nupkg' -Status Running
} | Write-ConsoleWidget

New-ConsoleTree '[bold]evotec.xyz[/]' {
    New-ConsoleTreeNode 'MX' -Status Pass -Detail '2 records' {
        New-ConsoleTreeNode 'evotec-xyz.mail.protection.outlook.com' -Detail 'priority 0'
    }
    New-ConsoleTreeNode 'SPF' -Status Warn -Detail '9 of 10 DNS lookups' {
        'include:spf.protection.outlook.com'
        'include:_spf.salesforce.com'
    }
    New-ConsoleTreeNode 'DMARC' -Status Fail -Detail 'p=none'
} | Write-ConsoleWidget

$groups = @(
    [pscustomobject] @{ Name = 'Domain Admins'; Health = 'Warn'; Note = '6 members'; Members = @(
        [pscustomobject] @{ Name = 'Tier 0 operators'; Health = 'Pass'; Members = @([pscustomobject] @{ Name = 'anna.k' }) }
        [pscustomobject] @{ Name = 'svc-backup'; Health = 'Fail'; Note = 'password never expires' }
    ) }
)
$groups | New-ConsoleTree 'Privileged groups' -ChildrenProperty Members -StatusProperty Health -DetailProperty Note | Write-ConsoleWidget

New-ConsoleTree '[bold]evotec.xyz[/]' {
    New-ConsoleTreeNode 'MX' -Status Pass -Detail '2 records' {
        New-ConsoleTreeNode 'evotec-xyz.mail.protection.outlook.com' -Detail 'priority 0'
    }
    New-ConsoleTreeNode 'DMARC' -Status Fail -Detail 'p=none'
} | Write-ConsoleWidget

New-ConsoleTree 'Domain controllers' {
    New-ConsoleTreeNode 'ad.adatum.com' { 'DC01', 'DC02' }
    New-ConsoleTreeNode 'eu.ad.adatum.com' -Status Warn -Detail 'one offline' { 'DC07' }
} | Write-ConsoleWidget

New-ConsoleTree 'Reports share' {
    New-ConsoleTreeNode 'Weekly' -Value 734003200 -Presenter Bytes
    New-ConsoleTreeNode 'Archive' -Value 9663676416 -Presenter Bytes -Status Warn
} | Write-ConsoleWidget

$d = New-ConsoleDashboard -Title 'Patch' { New-ConsolePanel -Title 'Servers' { New-ConsoleLanes }; New-ConsolePanel -Title 'Log' -Fill { New-ConsoleLog } }
'SRV1', 'SRV2', 'SRV3' | Start-ConsoleDashboard $d -Parallel -ThrottleLimit 3 {
    param($Server)
    Update-ConsoleLane -Key $Server -Status Running -Total 5
    1..5 | ForEach-Object { Start-Sleep -Milliseconds 300; Update-ConsoleLane -Key $Server -Result Pass }
    Write-Host "$Server patched"
    Update-ConsoleLane -Key $Server -Complete
}

$files = Get-ChildItem C:\Reports -File
$dashboard = New-ConsoleDashboard -Title 'Copy' { New-ConsoleProgress 'Reports' -Total $files.Count }
Start-ConsoleDashboard $dashboard -ArgumentList (,$files) {
    param($Files)
    foreach ($file in $Files) {
        Copy-Item $file.FullName D:\Backup
        Update-ConsoleProgress -Increment 1
    }
}

Use-ConsoleProgress {
    foreach ($i in 1..50) {
        Write-Progress -Activity 'Copying' -Status "File $i of 50" -PercentComplete ($i * 2)
        Start-Sleep -Milliseconds 50
    }
}

Write-ConsoleTree 'Replication' {
    New-ConsoleTreeNode 'DC01' -Status Pass -Detail 'last sync 42s ago'
    New-ConsoleTreeNode 'DC02' -Status Warn -Detail 'last sync 42 min ago'
}
